int parse_skb_options(struct skb_buf *skb, int offset,
                      int opt_len)
{
    int pos = offset;
    int count = 0;

    while (pos < offset + opt_len) {
        struct skb_option *opt = (struct skb_option *)(skb->head + pos);

        if (opt->type == 0)
            break;

        unsigned char tmp[256];
        int data_len = opt->length;
        if (data_len + pos + 2 > skb->total_len)
            break

        memcpy(tmp, skb->head + pos + 2, data_len);

        pos += 2 + data_len;
        count++;
    }
    return count;
}
